from collections import deque

def shortest_path(graph, source, target):
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    queue = deque([source])
    predecessors = {source: None}
    while queue:
        current = queue.popleft()
        for neighbour, weight in graph.get(current, []):
            new_distance = distances[current] + weight
            if new_distance < distances[neighbour]:
                distances[neighbour] = new_distance
                predecessors[neighbour] = current
                queue.append(neighbour)
    if distances[target] == float('inf'):
        return (float('inf'), None)
    else:
        path = deque()
        current = target
        while current is not None:
            path.appendleft(current)
            current = predecessors.get(current)
        return (distances[target], list(path))
graph = {'A': [('B', 1), ('C', 4)], 'B': [('C', 1), ('D', 4)], 'C': [('D', 1)], 'D': [('C', 2)]}
print(shortest_path(graph, 'A', 'D'))
print(shortest_path(graph, 'A', 'E'))

from collections import defaultdict, deque
import heapq

def shortest_path(graph, source, target):
    if source not in graph or target not in graph:
        return (float('inf'), None)
    distances = defaultdict(lambda: float('inf'))
    distances[source] = 0
    path = defaultdict(lambda: None)
    path[source] = []
    queue = [(0, source)]
    while queue:
        current_distance, current_node = heapq.heappop(queue)
        if current_node == target:
            break
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                path[neighbor] = list(path[current_node]) + [current_node]
                heapq.heappush(queue, (distance, neighbor))
    if distances[target] == float('inf'):
        return (float('inf'), None)
    else:
        path_to_target = path[target]
        shortest_path = [target]
        while path_to_target:
            shortest_path.append(path_to_target.pop())
        shortest_path.reverse()
        return (distances[target], shortest_path)
graph = {'A': [('B', 1), ('C', 4)], 'B': [('A', 1), ('D', 2)], 'C': [('A', 4), ('D', 3)], 'D': [('B', 2), ('C', 3)]}
print(shortest_path(graph, 'A', 'D'))
print(shortest_path(graph, 'A', 'E'))
